sys_script.script:
/**
 * UIBM Finding Status Sync
 * Table: x_snc_uibm_finding (before update)
 *
 * When a finding is marked as "addressed", automatically:
 * 1. Records who resolved it and when
 * 2. Updates the parent page health record's finding counts
 * 3. If it was the last critical finding, re-evaluates the page health gate
 */
(function() {
    try {
        // Set resolution metadata
        current.resolved_at = new GlideDateTime();
        current.resolved_by = gs.getUserID();

        // Update page health finding counts
        var pageSysId = current.page_sys_id.toString();
        if (pageSysId) {
            var grHealth = new GlideRecord('x_snc_uibm_page_health');
            grHealth.addQuery('page_sys_id', pageSysId);
            grHealth.query();

            if (grHealth.next()) {
                // Recount open findings by severity
                var critical = 0, warning = 0, info = 0;
                var grFindings = new GlideRecord('x_snc_uibm_finding');
                grFindings.addQuery('page_sys_id', pageSysId);
                grFindings.addQuery('status', 'open');
                grFindings.query();
                while (grFindings.next()) {
                    var sev = grFindings.severity.toString();
                    if (sev === 'critical') critical++;
                    else if (sev === 'warning') warning++;
                    else if (sev === 'info') info++;
                }

                grHealth.critical_findings = critical;
                grHealth.warning_findings = warning;
                grHealth.info_findings = info;
                grHealth.update();
            }
        }
    } catch (ex) {
        gs.logWarning('[UIBM Finding Sync] Error syncing finding status: ' + ex.message);
    }
})();
